// Kylas Self-Form — Translate form payload → Kylas API schema (double-quoted version)

const input = $input.first().json;

let form;
if (input.body && typeof input.body === "object") form = input.body;
else if (input.body && typeof input.body === "string") {
  try { form = JSON.parse(input.body); }
  catch (e) { throw new Error("Invalid JSON in webhook body: " + e.message); }
} else form = input;

const lead = form.lead || {};
const log  = form.log  || {};
const meta = form.meta || {};

const phone0 = (lead.phoneNumbers && lead.phoneNumbers[0]) || {};
if (!phone0.value)                                              throw new Error("Missing phone number");
if (!lead.source || !lead.source.id)                            throw new Error("Missing source");
if (!lead.leadType || !lead.leadType.id)                        throw new Error("Missing lead type");
if (!Array.isArray(lead.subSources) || !lead.subSources.length) throw new Error("Missing sub source");
if (!lead.ownerId)                                              throw new Error("Missing owner");

function toProperCase(s) {
  return String(s || "").split(/\s+/).filter(Boolean)
    .map(function(w){ return w[0].toUpperCase() + w.slice(1).toLowerCase(); }).join(" ");
}
function cleanNotes(s) {
  return String(s || "").replace(/[\r\n\t]+/g, " ").replace(/ {2,}/g, " ").trim();
}
function cleanDigits(s) {
  return String(s || "").replace(/[^0-9]/g, "");
}
function nonEmpty(s) {
  return s != null && String(s).trim().length > 0;
}

const fullNameInput = (log.full_name_input || log.full_name_final || "").trim();
const firstName = fullNameInput ? toProperCase(fullNameInput) : "Eagle";
const leadTypeCode = String(log.leadtype_code || log.leadtype_name || "LEAD")
  .toUpperCase().replace(/\s+/g, " ").trim();
const lastName = leadTypeCode + " SELF IMPORT FORM";

const now = new Date();
const ist = new Date(now.getTime() + (5.5 * 60 * 60 * 1000));
const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const pad = function(n){ return String(n).padStart(2, "0"); };
const h24 = ist.getUTCHours();
const h12 = h24 % 12 || 12;
const ampm = h24 >= 12 ? "PM" : "AM";
const timestampIst = pad(ist.getUTCDate()) + "-" + months[ist.getUTCMonth()] + "-" + ist.getUTCFullYear()
                   + " " + pad(h12) + ":" + pad(ist.getUTCMinutes()) + " " + ampm + " IST";

// customFieldValues — always include required, conditional optionals
const customFieldValues = {
  cfLeadType:               [ +lead.leadType.id ],
  cfSubSourceMultiPicklist: lead.subSources.map(function(ss){ return +ss.id; })
};
if (nonEmpty(lead.city)) customFieldValues.cfCity = String(lead.city).trim();
const notes = cleanNotes(lead.cfNotesFromLeadImport);
if (notes) customFieldValues.cfNotesFromLeadImport = notes;

// Main Kylas payload
const kylasPayload = {
  firstName: firstName,
  lastName: lastName,
  phoneNumbers: [{
    type: "MOBILE",
    code: log.country_iso || "IN",
    value: cleanDigits(phone0.value),
    dialCode: phone0.dialCode || "+91",
    primary: true
  }],
  source:  +lead.source.id,
  ownerId: +lead.ownerId,
  customFieldValues: customFieldValues
};

// Optional top-level UTM fields — omit if empty
if (nonEmpty(lead.utmSource))   kylasPayload.utmSource   = String(lead.utmSource);
if (nonEmpty(lead.utmMedium))   kylasPayload.utmMedium   = String(lead.utmMedium);
if (nonEmpty(lead.utmCampaign)) kylasPayload.utmCampaign = String(lead.utmCampaign);
if (nonEmpty(lead.utmContent))  kylasPayload.utmContent  = String(lead.utmContent);
if (nonEmpty(lead.utmTerm))     kylasPayload.utmTerm     = String(lead.utmTerm);

// Optional emails — omit entirely if blank
if (lead.emails && lead.emails[0] && nonEmpty(lead.emails[0].value)) {
  kylasPayload.emails = [{
    type: "OFFICE",
    value: String(lead.emails[0].value).trim().toLowerCase(),
    primary: true
  }];
}

return [{
  json: {
    kylasPayload: kylasPayload,
    formPayload: form,
    timestampIst: timestampIst
  }
}];

// ──────────────────────────────────────────────────────────────────
// Build Sheet Log Payload — detect Kylas success/failure, enrich the
// original form payload with `kylas_result` block so Apps Script can
// write a proper row (real lead ID + link, or failure + error message).
// ──────────────────────────────────────────────────────────────────

const prev = $('Translate to Kylas Schema').first().json;
const resp = $input.first().json;

const statusCode = resp.statusCode || 0;
const body = resp.body || {};

let kylasResult;
if (statusCode >= 200 && statusCode < 300 && body && body.id) {
  kylasResult = {
    status: 'Success',
    kylas_lead_id: String(body.id),
    kylas_lead_link: `https://app.kylas.io/sales/leads/details/${body.id}`,
    timestamp_ist: prev.timestampIst,
    error_message: ''
  };
} else {
  // Extract best-available Kylas error message for humans + audit
  let errMsg;
  if (body && typeof body === 'object') {
    errMsg = body.message || (body.error && (body.error.message || JSON.stringify(body.error))) || JSON.stringify(body);
  } else if (typeof body === 'string' && body.length) {
    errMsg = body;
  } else {
    errMsg = 'No response body from Kylas';
  }
  // Cap length to keep sheet cell readable
  errMsg = String(errMsg).slice(0, 500);
  kylasResult = {
    status: 'Failed',
    kylas_lead_id: '',
    kylas_lead_link: '',
    timestamp_ist: prev.timestampIst,
    error_message: `HTTP ${statusCode}: ${errMsg}`
  };
}

// Enrich original form payload with kylas_result — Apps Script reads this
// to decide real-ID-row vs STUB-row behaviour.
const enriched = Object.assign({}, prev.formPayload, { kylas_result: kylasResult });

return [{ json: { sheetPayload: enriched, kylasResult: kylasResult } }];
